@startuml

class Aircraft {
  + name : string
  + type : string
  + yearOfManufacture : int
  + nextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + numberOfSeats : int
}

class SeatCategory {
  + designation : string
  + offersEntertainment : boolean
  + numberOfSeats : int
}

class Passenger {
  + name : string
  + passportNumber : string
}

class Ticket {
  + ticketNumber : string
  + price : float
  + upgradeDesired : boolean
}

class Flight {
  + flightNumber : string
  + date : date
}

class Airline {
  + name : string
}

class FlightAttendant {
  + name : string
  + employmentDate : date
  + isChiefStewardess : boolean
}

class Pilot {
  + name : string
  + employmentDate : date
  + license : string
}

class Airport {
  + name : string
  + address : string
  + numberOfRunways : int
}

Aircraft "0..*" -- "0..1" Airline : belongs to
PassengerAircraft "1" *-- "1..*" SeatCategory : has
Aircraft "1" -- "*" Flight : performs
Flight "1" -- "*" Passenger : involves
Passenger "1" -- "*" Ticket : holds
Flight "1" -- "*" Ticket : issued for
SeatCategory "1" -- "*" Ticket : assigned to
Flight "1" -- "1..*" FlightAttendant : staffed by
Flight "1" -- "1" Pilot : captained by
Flight "1" -- "1..2" Pilot : co-piloted by
Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives at
Aircraft "*" -- "0..1" Airport : home airport

@enduml

